const note = sticky("## CEO Brain — Approval Inbox (human task inbox)\nGET /webhook/ceo-brain/inbox — one page with everything waiting for a human: approvals (Approve & send / Reject go through the existing Approve Reply gate), exceptions to recover, leads needing a human, overdue follow-ups, stale leads.\nPOST /webhook/ceo-brain/inbox {pin, action close|recover|reopen|cancel, task_id} — closes/recovers a task with an audit row. The PIN lives ONLY in the \"Inbox Config\" node (change it there; same PIN as the Trainer Config by default).\n\nSource of truth: ryan/ceo-brain/workflows/approval-inbox/build.js (issue logic shared with the CEO Orchestrator). Do not hand-edit Code nodes.", [page, getTasks, action, config], { color: 4 });

export default workflow('ceo-brain-approval-inbox', 'CEO Brain — Approval Inbox')
  .add(page)
  .to(getTasks)
  .to(getLeads)
  .to(getRuns)
  .to(getDrafts)
  .to(render)
  .to(serve)
  .add(action)
  .to(config)
  .to(validate)
  .to(isOk
    .onTrue(updateTask.to(auditAction).to(respondOk))
    .onFalse(respondError))
  .add(note);
